insert into sys_project_copy_job (
    job_id, source_project_id, target_project_id, state, percent,
    selection_json, items_json, estimated_bytes, actual_bytes, error_message,
    create_by, create_time, update_time
) values (
    #{jobId}, #{sourceProjectId}, #{targetProjectId}, #{state}, #{percent},
    #{selectionJson}, #{itemsJson}, #{estimatedBytes}, #{actualBytes}, #{errorMessage},
    #{createBy}, #{createTime}, #{updateTime}
)

mapper.select:
select count(1)
from sys_user_project up
join sys_user_project_role upr on upr.user_project_id = up.user_project_id
where up.user_id = #{userId}
  and up.project_id = #{projectId}
  and upr.role_id in (11, 6)
